steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "{
      teams {
        nodes {
          id
          name
          key
        }
      }
      issues(first: 50) {
        nodes {
          id
          identifier
          title
          description
          priority
          priorityName
          completedAt
          workflowState {
            name
          }
          team {
            name
            key
          }
          project {
            name
          }
        }
      }
    }
  }'
